_NEWS_ALIAS = {
    "wotlk-classic": "wotlk",
    "cata-classic": "cata",
}
_FEATURE_ALIAS = {
    "classic-era": "vanilla",
    "wotlk-classic": "wotlk",
    "cata-classic": "cata",
}


def news_for(exp: Expansion) -> list[tuple[str, str, str]]:
    if exp.id == "classic-era":
        return [
            (
                "Classic Era",
                "2019-08-26",
                "This realm serves the Classic Era client. It is not the 2006 community site.",
            )
        ]
    key = _NEWS_ALIAS.get(exp.id, exp.id)
    return list(NEWS.get(key, ()))


def features_for(exp: Expansion) -> list[str]:
    key = _FEATURE_ALIAS.get(exp.id, exp.id)
    return list(FEATURES.get(key, ()))


def intro_blurb(exp: Expansion) -> str:
    return (
        f"{exp.name} as it stood at patch {exp.last_patch} ({exp.last_patch_date})."
    )
